// CONFIG — Normalise: the Config tab is Key | Value rows. Turn them into
// one config object every later node in this branch can read, with safe
// defaults for anything not filled in yet. The sheet drives everything:
// niche, language, voice, upload days, publish time, approval mode and
// the uploads_paused kill-switch the chat agent flips.
let rows = [];
try { rows = $input.all().map(i => i.json); } catch (e) { rows = []; }
const raw = {};
for (const r of rows) {
  const k = String(r['Key'] || '').trim();
  if (k) raw[k] = r['Value'] === undefined || r['Value'] === null ? '' : String(r['Value']).trim();
}
const daysMap = { sun: 0, mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6 };
const uploadDays = String(raw.upload_days || 'Mon, Wed, Fri').split(',')
  .map(s => daysMap[s.trim().toLowerCase().slice(0, 3)])
  .filter(v => v !== undefined);
const cfg = {
  config_channel_name: raw.channel_name || 'My Channel',
  config_channel_id: raw.channel_id || '',
  config_niche: raw.niche || '',
  config_language: raw.language || 'English',
  config_voice: raw.voice || 'default',
  config_visual_style: raw.visual_style || 'clean flat vector illustration, consistent characters, no text in the image',
  config_upload_days: uploadDays,
  config_upload_days_raw: raw.upload_days || 'Mon, Wed, Fri',
  config_publish_time: raw.publish_time || '18:00',
  config_approval_mode: String(raw.approval_mode || 'APPROVE').toUpperCase() === 'AUTO' ? 'AUTO' : 'APPROVE',
  config_uploads_paused: String(raw.uploads_paused || 'FALSE').toUpperCase() === 'TRUE',
  config_chat_app: String(raw.chat_app || 'whatsapp').toLowerCase() === 'telegram' ? 'telegram' : 'whatsapp',
  config_owner_whatsapp_number: String(raw.owner_whatsapp_number || '').replace(/\D/g, ''),
  config_owner_telegram_chat_id: raw.owner_telegram_chat_id || '',
  config_aspect: raw.aspect_ratio || '16:9',
  config_scene_seconds: parseInt(raw.scene_seconds, 10) || 6,
  config_recent_days: parseInt(raw.digest_recent_days, 10) || 28,
  config_max_digest_videos: parseInt(raw.digest_max_videos, 10) || 10,
  config_flow_endpoint: raw.video_module_endpoint || '',
  config_tts_endpoint: raw.tts_endpoint || '',
  config_render_endpoint: raw.render_endpoint || '',
  config_image_endpoint: raw.image_endpoint || ''
};
return [{ json: cfg }];

// Schedule Gate — the sheet decides whether today is a production day.
// uploads_paused = TRUE (the chat kill-switch) or a weekday outside
// config_upload_days ends the run silently: returning [] means "not
// today", exactly like the rest of the catalogue — silence is the answer.
const cfg = $input.first().json;
if (cfg.config_uploads_paused) return [];
const today = new Date().getDay();
if (Array.isArray(cfg.config_upload_days) && cfg.config_upload_days.length &&
    !cfg.config_upload_days.includes(today)) return [];
return [{ json: { ...cfg, proceed: true,
  run_date: new Date().toISOString().slice(0, 10) } }];

// Pick Next Topic — the first Topics row whose Status is Queued (or
// blank) and whose Topic does NOT already appear in the Videos log.
// That dedupe is what stops the channel repeating itself when the
// queue is edited by hand or a run is repeated. No queued topic left?
// Flag needs_brainstorm and let the brainstorm branch stock the queue
// with candidates — candidates are never produced unapproved.
let topics = [];
try { topics = $('Read Topics Queue').all().map(i => i.json); } catch (e) { topics = []; }
let cfg = {};
try { cfg = $('CONFIG — Normalise').first().json; } catch (e) { cfg = {}; }
const videos = $input.all().map(i => i.json);
const used = new Set(videos.map(v => String(v['Topic'] || '').trim().toLowerCase()).filter(Boolean));
const next = topics.find(t => {
  const title = String(t['Topic'] || '').trim();
  const status = String(t['Status'] || '').trim().toLowerCase();
  return title && (status === 'queued' || status === '') && !used.has(title.toLowerCase());
});
if (!next) return [{ json: { ...cfg, topic_found: false, needs_brainstorm: true } }];
return [{ json: { ...cfg, topic_found: true, needs_brainstorm: false,
  topic: String(next['Topic']).trim(), angle: String(next['Angle'] || '').trim() } }];

// Save Brainstorm Candidates — parse the model's JSON into Topics rows
// stamped 'Candidate — needs approval'. They enter the queue ONLY when
// the owner flips a row to Queued (in the sheet or by chat). A reply we
// cannot parse still yields simple line-by-line candidates rather than
// losing the run.
let content = '';
try { content = $input.first().json.choices[0].message.content || ''; } catch (e) { content = ''; }
let list = [];
try {
  const parsed = JSON.parse(content);
  if (Array.isArray(parsed.topics)) list = parsed.topics;
} catch (e) {
  list = content.split('\n').map(s => s.replace(/^[-*0-9.)\s]+/, '').trim())
    .filter(Boolean).map(t => ({ topic: t, angle: '' }));
}
const today = new Date().toISOString().slice(0, 10);
return list.slice(0, 5).map(t => ({ json: {
  'Topic': String(t.topic || '').trim(),
  'Angle': String(t.angle || '').trim(),
  'Status': 'Candidate — needs approval',
  'Added': today
} })).filter(r => r.json['Topic']);

// Prepare Scenes for the Video Module — normalise the writer's JSON
// into one module-ready item per scene: numbered, defaults filled,
// empty scenes dropped. The Video Module receives EXACTLY these fields
// per scene (its contract): scene_number, prompt, narration,
// aspect_ratio, duration_seconds. Everything downstream of the module
// expects clip URLs back in the same order.
let content = '';
try { content = $input.first().json.choices[0].message.content || ''; } catch (e) { content = ''; }
let parsed = {};
try { parsed = JSON.parse(content); } catch (e) { parsed = {}; }
let pick = {};
try { pick = $('Pick Next Topic').first().json; } catch (e) { pick = {}; }
const scenes = Array.isArray(parsed.scenes) ? parsed.scenes : [];
const clean = scenes
  .map(s => ({
    narration: String((s && s.narration) || '').trim(),
    prompt: String((s && s.visual_prompt) || '').trim()
  }))
  .filter(s => s.narration && s.prompt)
  .map((s, i) => ({ scene_number: i + 1, narration: s.narration, prompt: s.prompt }));
const scriptFull = clean.map(s => s.narration).join(' ');
return clean.map(s => ({ json: {
  ...s,
  aspect_ratio: pick.config_aspect || '16:9',
  duration_seconds: pick.config_scene_seconds || 6,
  topic: pick.topic || '',
  working_title: String(parsed.working_title || pick.topic || '').trim(),
  hook: String(parsed.hook || '').trim(),
  script_full: scriptFull,
  scene_count: clean.length
} }));

// Collect Scene Clips — gather the module's per-scene outputs back into
// ONE production item, matched to the prepared scenes by scene_number.
// Any scene without a clip_url marks the package failed: a video with a
// silent gap is worse than no video, so the run stops and alerts.
let scenes = [];
try { scenes = $('Prepare Scenes for Video Module').all().map(i => i.json); } catch (e) { scenes = []; }
const outs = $input.all().map(i => i.json);
const byScene = {};
for (const o of outs) {
  const n = o && o.scene_number !== undefined ? Number(o.scene_number) : null;
  if (n !== null && o.clip_url) byScene[n] = String(o.clip_url);
}
const clips = scenes.map(s => ({
  scene_number: s.scene_number,
  narration: s.narration,
  clip_url: byScene[s.scene_number] || ''
}));
const missing = clips.filter(c => !c.clip_url).map(c => c.scene_number);
const first = scenes[0] || {};
return [{ json: {
  topic: first.topic || '', working_title: first.working_title || '',
  hook: first.hook || '', script_full: first.script_full || '',
  scene_count: clips.length, clips: clips,
  module_failed: missing.length > 0, missing_scenes: missing
} }];

// Build Render Request — assemble the render-endpoint payload exactly
// per the documented contract: the module's clips in scene order, the
// voiceover, and subtitles burned in from the narration text (so the
// words on screen are the words spoken — never a separate transcript
// that can drift). The endpoint returns { video_url }.
let prod = {};
try { prod = $('Collect Scene Clips').first().json; } catch (e) { prod = $input.first().json; }
let cfg = {};
try { cfg = $('CONFIG — Normalise').first().json; } catch (e) { cfg = {}; }
const audioUrl = ($input.first().json && $input.first().json.audio_url) || '';
const slug = String(prod.topic || 'video').toLowerCase().replace(/[^a-z0-9]+/g, '-').slice(0, 40);
const renderRequest = {
  render_key: slug + '-' + new Date().toISOString().slice(0, 10),
  clips: (prod.clips || []).map(c => ({ scene: c.scene_number, url: c.clip_url, narration: c.narration })),
  audio_url: audioUrl,
  subtitles: { burn_in: true, source: 'narration', language: cfg.config_language || 'English' },
  aspect_ratio: cfg.config_aspect || '16:9',
  format: 'mp4'
};
return [{ json: { render_request: renderRequest, topic: prod.topic || '',
  working_title: prod.working_title || '', script_full: prod.script_full || '' } }];

// Parse Metadata — pull the pack out of the model's JSON and merge it
// with the render result. Chapters fall back to scene-based timestamps
// (scene length x position, titled from each scene's first words) when
// the model returns none, so a package never ships without chapters.
let content = '';
try { content = $input.first().json.choices[0].message.content || ''; } catch (e) { content = ''; }
let meta = {};
try { meta = JSON.parse(content); } catch (e) { meta = {}; }
let render = {};
try { render = $('Render Video (Assembly Endpoint)').first().json; } catch (e) { render = {}; }
let build = {};
try { build = $('Build Render Request').first().json; } catch (e) { build = {}; }
let chapters = String(meta.chapters || '').trim();
if (!chapters) {
  let scenes = [];
  try { scenes = $('Prepare Scenes for Video Module').all().map(i => i.json); } catch (e) { scenes = []; }
  let pick = {};
  try { pick = $('CONFIG — Normalise').first().json; } catch (e) { pick = {}; }
  const per = pick.config_scene_seconds || 6;
  chapters = scenes.map((s, i) => {
    const t = i * per;
    const mm = String(Math.floor(t / 60)).padStart(2, '0');
    const ss = String(t % 60).padStart(2, '0');
    const label = String(s.narration || '').split(' ').slice(0, 4).join(' ') || ('Part ' + (i + 1));
    return mm + ':' + ss + ' ' + label;
  }).join('\n');
}
const tags = Array.isArray(meta.tags) ? meta.tags.join(', ') : String(meta.tags || '');
return [{ json: {
  title: String(meta.title || build.working_title || '').trim(),
  description: String(meta.description || '').trim(),
  tags: tags, chapters: chapters,
  video_url: String(render.video_url || ''),
  duration_seconds: render.duration_seconds || '',
  topic: build.topic || '', working_title: build.working_title || '',
  script_full: build.script_full || ''
} }];

// Finalise Package — merge the thumbnail with the metadata, mint the
// Package ID the owner will approve by, work out Publish At (today at
// config_publish_time; if that moment has passed, the next upload day
// at that time), and set the Status from the approval mode:
// APPROVE -> AWAITING_APPROVAL (the uploader will not touch it),
// AUTO -> READY (the uploader may publish it at Publish At).
let meta = {};
try { meta = $('Parse Metadata').first().json; } catch (e) { meta = {}; }
let cfg = {};
try { cfg = $('CONFIG — Normalise').first().json; } catch (e) { cfg = {}; }
const thumb = ($input.first().json && $input.first().json.image_url) || '';
const now = new Date();
const pad = n => String(n).padStart(2, '0');
const stamp = d => d.getFullYear() + pad(d.getMonth() + 1) + pad(d.getDate());
const packageId = 'VID-' + stamp(now) + '-' + Math.floor(10 + Math.random() * 89);
const parts = String(cfg.config_publish_time || '18:00').split(':');
const hh = parseInt(parts[0], 10) || 18, mm = parseInt(parts[1], 10) || 0;
const days = Array.isArray(cfg.config_upload_days) && cfg.config_upload_days.length
  ? cfg.config_upload_days : [now.getDay()];
let publish = new Date(now.getFullYear(), now.getMonth(), now.getDate(), hh, mm);
for (let add = 0; add < 8; add++) {
  const cand = new Date(now.getFullYear(), now.getMonth(), now.getDate() + add, hh, mm);
  if (cand > now && days.includes(cand.getDay())) { publish = cand; break; }
  publish = cand;
}
const fmtDT = d => d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) +
  ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes());
const approvalRequired = cfg.config_approval_mode !== 'AUTO';
const status = approvalRequired ? 'AWAITING_APPROVAL' : 'READY';
const approvalMsg = [
  '🎬 New video ready for your approval — ' + packageId,
  'Title: ' + meta.title,
  'Publishes: ' + fmtDT(publish) + ' (once approved)',
  'Preview: ' + meta.video_url,
  'Thumbnail: ' + thumb,
  '',
  'Reply APPROVE ' + packageId + ' to publish, or REJECT ' + packageId + ' to bin it.'
].join('\n');
const autoMsg = '🎬 New video packaged (' + packageId + '): "' + meta.title + '" — ' +
  'approval mode is AUTO, so it publishes at ' + fmtDT(publish) + '. Preview: ' + meta.video_url;
return [{ json: {
  'Package ID': packageId, 'Topic': meta.topic || '', 'Title': meta.title || '',
  'Description': meta.description || '', 'Tags': meta.tags || '',
  'Chapters': meta.chapters || '', 'Video URL': meta.video_url || '',
  'Thumbnail URL': thumb, 'Publish At': fmtDT(publish), 'Status': status,
  'YouTube URL': '', 'Created At': fmtDT(now),
  approval_required: approvalRequired, approval_message: approvalMsg,
  auto_message: autoMsg,
  config_chat_app: cfg.config_chat_app || 'whatsapp',
  config_owner_whatsapp_number: cfg.config_owner_whatsapp_number || '',
  config_owner_telegram_chat_id: cfg.config_owner_telegram_chat_id || ''
} }];

// CONFIG — Normalise: the Config tab is Key | Value rows. Turn them into
// one config object every later node in this branch can read, with safe
// defaults for anything not filled in yet. The sheet drives everything:
// niche, language, voice, upload days, publish time, approval mode and
// the uploads_paused kill-switch the chat agent flips.
let rows = [];
try { rows = $input.all().map(i => i.json); } catch (e) { rows = []; }
const raw = {};
for (const r of rows) {
  const k = String(r['Key'] || '').trim();
  if (k) raw[k] = r['Value'] === undefined || r['Value'] === null ? '' : String(r['Value']).trim();
}
const daysMap = { sun: 0, mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6 };
const uploadDays = String(raw.upload_days || 'Mon, Wed, Fri').split(',')
  .map(s => daysMap[s.trim().toLowerCase().slice(0, 3)])
  .filter(v => v !== undefined);
const cfg = {
  config_channel_name: raw.channel_name || 'My Channel',
  config_channel_id: raw.channel_id || '',
  config_niche: raw.niche || '',
  config_language: raw.language || 'English',
  config_voice: raw.voice || 'default',
  config_visual_style: raw.visual_style || 'clean flat vector illustration, consistent characters, no text in the image',
  config_upload_days: uploadDays,
  config_upload_days_raw: raw.upload_days || 'Mon, Wed, Fri',
  config_publish_time: raw.publish_time || '18:00',
  config_approval_mode: String(raw.approval_mode || 'APPROVE').toUpperCase() === 'AUTO' ? 'AUTO' : 'APPROVE',
  config_uploads_paused: String(raw.uploads_paused || 'FALSE').toUpperCase() === 'TRUE',
  config_chat_app: String(raw.chat_app || 'whatsapp').toLowerCase() === 'telegram' ? 'telegram' : 'whatsapp',
  config_owner_whatsapp_number: String(raw.owner_whatsapp_number || '').replace(/\D/g, ''),
  config_owner_telegram_chat_id: raw.owner_telegram_chat_id || '',
  config_aspect: raw.aspect_ratio || '16:9',
  config_scene_seconds: parseInt(raw.scene_seconds, 10) || 6,
  config_recent_days: parseInt(raw.digest_recent_days, 10) || 28,
  config_max_digest_videos: parseInt(raw.digest_max_videos, 10) || 10,
  config_flow_endpoint: raw.video_module_endpoint || '',
  config_tts_endpoint: raw.tts_endpoint || '',
  config_render_endpoint: raw.render_endpoint || '',
  config_image_endpoint: raw.image_endpoint || ''
};
return [{ json: cfg }];

// Pick Due Video — the uploader's whole discipline in one place:
//  - uploads_paused = TRUE stops everything (the chat kill-switch)
//  - only APPROVED (human said yes) or READY (AUTO mode) packages
//  - only when Publish At has actually arrived
//  - ONE video per run, earliest first — never a burst
// Nothing due = [] and the run is silent.
let cfg = {};
try { cfg = $('CONFIG — Normalise (Upload)').first().json; } catch (e) { cfg = {}; }
if (cfg.config_uploads_paused) return [];
const rows = $input.all().map(i => i.json);
const now = new Date();
const due = rows
  .filter(r => ['APPROVED', 'READY'].includes(String(r['Status'] || '').toUpperCase()))
  .map(r => ({ r: r, t: new Date(String(r['Publish At'] || '').replace(' ', 'T')) }))
  .filter(x => !isNaN(x.t) && x.t <= now)
  .sort((a, b) => a.t - b.t)[0];
if (!due) return [];
const r = due.r;
return [{ json: { ...r,
  package_id: r['Package ID'] || '', topic: r['Topic'] || '',
  title: r['Title'] || '', description: r['Description'] || '',
  tags: r['Tags'] || '', video_url: r['Video URL'] || '',
  thumbnail_url: r['Thumbnail URL'] || '', publish_at: r['Publish At'] || '',
  due: true } }];

// CONFIG — Normalise: the Config tab is Key | Value rows. Turn them into
// one config object every later node in this branch can read, with safe
// defaults for anything not filled in yet. The sheet drives everything:
// niche, language, voice, upload days, publish time, approval mode and
// the uploads_paused kill-switch the chat agent flips.
let rows = [];
try { rows = $input.all().map(i => i.json); } catch (e) { rows = []; }
const raw = {};
for (const r of rows) {
  const k = String(r['Key'] || '').trim();
  if (k) raw[k] = r['Value'] === undefined || r['Value'] === null ? '' : String(r['Value']).trim();
}
const daysMap = { sun: 0, mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6 };
const uploadDays = String(raw.upload_days || 'Mon, Wed, Fri').split(',')
  .map(s => daysMap[s.trim().toLowerCase().slice(0, 3)])
  .filter(v => v !== undefined);
const cfg = {
  config_channel_name: raw.channel_name || 'My Channel',
  config_channel_id: raw.channel_id || '',
  config_niche: raw.niche || '',
  config_language: raw.language || 'English',
  config_voice: raw.voice || 'default',
  config_visual_style: raw.visual_style || 'clean flat vector illustration, consistent characters, no text in the image',
  config_upload_days: uploadDays,
  config_upload_days_raw: raw.upload_days || 'Mon, Wed, Fri',
  config_publish_time: raw.publish_time || '18:00',
  config_approval_mode: String(raw.approval_mode || 'APPROVE').toUpperCase() === 'AUTO' ? 'AUTO' : 'APPROVE',
  config_uploads_paused: String(raw.uploads_paused || 'FALSE').toUpperCase() === 'TRUE',
  config_chat_app: String(raw.chat_app || 'whatsapp').toLowerCase() === 'telegram' ? 'telegram' : 'whatsapp',
  config_owner_whatsapp_number: String(raw.owner_whatsapp_number || '').replace(/\D/g, ''),
  config_owner_telegram_chat_id: raw.owner_telegram_chat_id || '',
  config_aspect: raw.aspect_ratio || '16:9',
  config_scene_seconds: parseInt(raw.scene_seconds, 10) || 6,
  config_recent_days: parseInt(raw.digest_recent_days, 10) || 28,
  config_max_digest_videos: parseInt(raw.digest_max_videos, 10) || 10,
  config_flow_endpoint: raw.video_module_endpoint || '',
  config_tts_endpoint: raw.tts_endpoint || '',
  config_render_endpoint: raw.render_endpoint || '',
  config_image_endpoint: raw.image_endpoint || ''
};
return [{ json: cfg }];

// Pick Recent Videos — the digest covers the videos in the Videos log
// published inside the config_recent_days window (default 28), newest
// first, capped at config_max_digest_videos so one digest stays one
// message. Videos with an unparseable Published At are kept (a typo in
// the log should not make a video invisible).
let cfg = {};
try { cfg = $('CONFIG — Normalise (Reporting)').first().json; } catch (e) { cfg = {}; }
const days = cfg.config_recent_days || 28;
const cap = cfg.config_max_digest_videos || 10;
const cutoff = Date.now() - days * 24 * 60 * 60 * 1000;
const rows = $input.all().map(i => i.json)
  .filter(r => String(r['Video ID'] || '').trim())
  .map(r => ({ r: r, t: new Date(r['Published At']).getTime() }))
  .filter(x => isNaN(x.t) || x.t >= cutoff)
  .sort((a, b) => (isNaN(b.t) ? 0 : b.t) - (isNaN(a.t) ? 0 : a.t))
  .slice(0, cap);
return rows.map(x => ({ json: {
  video_id: String(x.r['Video ID']).trim(),
  video_title: String(x.r['Title'] || '').trim()
} }));

// Prepare Stats Rows — turn each videos.list response into one Stats
// snapshot row for today (Date | Video ID | Title | Views | Likes |
// Comments). Counts arrive as strings; store numbers. A video whose
// stats call failed simply has no row today — the digest says so
// rather than inventing a zero.
let picked = [];
try { picked = $('Pick Recent Videos').all().map(i => i.json); } catch (e) { picked = []; }
const titleById = {};
for (const p of picked) titleById[p.video_id] = p.video_title;
const today = new Date().toISOString().slice(0, 10);
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const v = j.items && j.items[0];
  if (!v || !v.id) continue;
  const st = v.statistics || {};
  const num = x => { const n = parseInt(x, 10); return isNaN(n) ? 0 : n; };
  out.push({ json: {
    'Date': today, 'Video ID': v.id,
    'Title': (v.snippet && v.snippet.title) || titleById[v.id] || '',
    'Views': num(st.viewCount), 'Likes': num(st.likeCount),
    'Comments': num(st.commentCount),
    video_id: v.id, video_title: (v.snippet && v.snippet.title) || titleById[v.id] || ''
  } });
}
return out;

// Build Comment Rows — new comments only: anything whose Comment ID
// already sits in the Comments tab is dropped (the dedupe), so re-runs
// never draft the same reply twice. Each new comment gets a DRAFT reply
// beside it — a starting point for the owner, NEVER a posted reply.
// Questions get a draft with an honest [your answer here] gap: a warm
// guess posted under your name would be worse than a short wait.
let responses = [];
try { responses = $('Fetch Comments').all().map(i => i.json); } catch (e) { responses = []; }
const known = new Set($input.all().map(i => String(i.json['Comment ID'] || '').trim()).filter(Boolean));
let titles = {};
try {
  for (const p of $('Pick Recent Videos').all()) titles[p.json.video_id] = p.json.video_title;
} catch (e) { titles = {}; }
const draftFor = (author, text) => {
  const first = String(author || 'there').split(' ')[0] || 'there';
  if (String(text).includes('?')) {
    return 'Thanks for the question, ' + first + '! Short answer: [your answer here] — ' +
      'and a fuller breakdown is on the way in an upcoming video. Really appreciate you watching!';
  }
  const openers = [
    'Thank you, ' + first + '! Glad this one helped.',
    'Really appreciate that, ' + first + ' — thanks for watching!',
    'That means a lot, ' + first + '! More like this coming soon.'
  ];
  let h = 0;
  const s = String(author || '') + String(text || '');
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
  return openers[h % openers.length];
};
const out = [];
for (const resp of responses) {
  const threads = (resp && resp.items) || [];
  for (const th of threads) {
    const top = th.snippet && th.snippet.topLevelComment;
    if (!top || !top.id || known.has(String(top.id))) continue;
    const sn = top.snippet || {};
    const videoId = th.snippet.videoId || sn.videoId || '';
    const text = String(sn.textDisplay || sn.textOriginal || '').trim();
    out.push({ json: {
      'Comment ID': String(top.id), 'Video ID': videoId,
      'Video Title': titles[videoId] || '',
      'Author': String(sn.authorDisplayName || ''),
      'Comment': text,
      'Published At': String(sn.publishedAt || ''),
      'Draft Reply': draftFor(sn.authorDisplayName, text),
      'Status': 'Draft — awaiting your approval',
      is_new_comment: true
    } });
    known.add(String(top.id));
  }
}
return out;

// Assemble Digest — one message for the owner: today's numbers for the
// recent videos, plus how many comment drafts are waiting. Everything
// is counted from the nodes that produced it, and a quiet channel is
// reported honestly as quiet — never padded.
let stats = [];
try { stats = $('Prepare Stats Rows').all().map(i => i.json); } catch (e) { stats = []; }
let comments = [];
try { comments = $('Build Comment Rows').all().map(i => i.json).filter(j => j && j.is_new_comment); } catch (e) { comments = []; }
let cfg = {};
try { cfg = $('CONFIG — Normalise (Reporting)').first().json; } catch (e) { cfg = {}; }
const today = new Date().toISOString().slice(0, 10);
const lines = ['📊 ' + (cfg.config_channel_name || 'Channel') + ' — daily digest (' + today + ')', ''];
if (!stats.length) {
  lines.push('No videos in the recent window yet — the digest fills in once the Videos log has entries.');
} else {
  let totalViews = 0;
  for (const s of stats) {
    totalViews += Number(s['Views'] || 0);
    lines.push('• ' + s['Title'] + ' — ' + Number(s['Views'] || 0).toLocaleString('en-US') +
      ' views · ' + Number(s['Likes'] || 0).toLocaleString('en-US') + ' likes · ' +
      Number(s['Comments'] || 0).toLocaleString('en-US') + ' comments');
  }
  lines.push('');
  lines.push('Total views across these ' + stats.length + ' video(s): ' + totalViews.toLocaleString('en-US'));
}
lines.push('');
if (comments.length) {
  const authors = [...new Set(comments.map(c => c['Author']).filter(Boolean))].slice(0, 5).join(', ');
  lines.push('💬 ' + comments.length + ' new comment(s) drafted in the Comments tab' +
    (authors ? ' (from ' + authors + ')' : '') + ' — drafts only; nothing was posted.');
} else {
  lines.push('💬 No new comments since the last digest.');
}
return [{ json: { digest_text: lines.join('\n'),
  config_chat_app: cfg.config_chat_app || 'whatsapp',
  config_owner_whatsapp_number: cfg.config_owner_whatsapp_number || '',
  config_owner_telegram_chat_id: cfg.config_owner_telegram_chat_id || '' } }];

