// Normalise Inbound: either chat app's webhook payload becomes ONE
// standard item — { chat_app, sender_id, sender_name, chat_text } — so the
// gate, the agent and the approval logic never care which app a message
// arrived on. Non-text events (WhatsApp delivery receipts, Telegram
// service messages) return nothing and end the run silently.
const j = $input.first().json || {};
const change = j.entry && j.entry[0] && j.entry[0].changes && j.entry[0].changes[0]
  ? j.entry[0].changes[0].value : null;
const msg = change && change.messages ? change.messages[0] : null;
if (msg) {
  if (msg.type !== 'text' || !msg.text || !msg.text.body) return [];
  const profile = change.contacts && change.contacts[0] && change.contacts[0].profile
    ? change.contacts[0].profile.name || '' : '';
  return [{ json: { chat_app: 'whatsapp', sender_id: String(msg.from || ''),
    sender_name: profile, chat_text: String(msg.text.body).trim(),
    chat_message_id: msg.id || '' } }];
}
const tm = j.message;
if (tm) {
  if (!tm.text) return [];
  return [{ json: { chat_app: 'telegram',
    sender_id: String(tm.chat && tm.chat.id !== undefined ? tm.chat.id : ''),
    sender_name: (tm.from && tm.from.first_name) || '',
    chat_text: String(tm.text).trim(),
    chat_message_id: String(tm.message_id !== undefined ? tm.message_id : '') } }];
}
return [];

// Chat Gate — Owner Allowlist: only the owner's own identity may command
// or approve. Reads the Config rows (this node's input), takes the
// normalised inbound item from 'Normalise Inbound', and lets exactly one
// identity through: on WhatsApp the sender number must equal
// owner_whatsapp_number, on Telegram the chat ID must equal
// owner_telegram_chat_id. Anything else — strangers, other numbers, group
// chats — is dropped silently. Replies always return on the channel the
// command arrived on (the item's own chat_app), whatever chat_app says.
const rows = $input.all().map(i => i.json);
const raw = {};
for (const r of rows) {
  const k = String(r['Key'] || '').trim();
  if (k) raw[k] = r['Value'] === undefined || r['Value'] === null ? '' : String(r['Value']).trim();
}
let inbound = {};
try { inbound = $('Normalise Inbound').first().json; } catch (e) { inbound = {}; }
const digits = s => String(s || '').replace(/\D/g, '');
let allowed = false;
if (inbound.chat_app === 'whatsapp') {
  const owner = digits(raw.owner_whatsapp_number);
  allowed = !!owner && digits(inbound.sender_id) === owner;
} else if (inbound.chat_app === 'telegram') {
  const owner = String(raw.owner_telegram_chat_id || '').trim();
  allowed = !!owner && String(inbound.sender_id || '').trim() === owner;
}
if (!allowed || !inbound.chat_text) return [];
return [{ json: inbound }];
